"""Two complete original highest entrance brow front rectangles."""
from pathlib import Path
import numpy as np,trimesh,json,hashlib
R=Path(__file__).resolve().parent;H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();expected='85bfde8fc1fd94aba8d838a41cb7faf6e47199c387ac8649f277cc41c90b86c5';assert H(R/'model.stl')==expected
m=trimesh.load(R/'model.stl',force='mesh',process=True);assert len(m.faces)==2860
t=m.triangles;n=m.face_normals;e=.0001;a=np.full(len(t),1,np.int32);D={}
ids=np.flatnonzero(np.abs(t[:,:,1]+14).max(1)<e)
assert len(ids)==4
edges=m.face_adjacency;edges=edges[np.isin(edges[:,0],ids)&np.isin(edges[:,1],ids)]
pcs=trimesh.graph.connected_components(edges,nodes=ids,min_len=1);assert sorted(map(len,pcs))==[2,2]
D['complete_twin_upper_brow_fronts']=ids.tolist();a[ids]=0
ad=m.face_adjacency;cop=(n[ad[:,0]]*n[ad[:,1]]).sum(1)>.999999;cs=trimesh.graph.connected_components(ad[cop],nodes=np.arange(len(t)),min_len=1);assert all(len(set(a[c]))==1 for c in cs);assert np.bincount(a).tolist()==[4,2856]
pal=[('NTOU Matsu Dorm Entrance Section observed twin highest brow front lightgray','#C7CBC8'),('UNVERIFIED main walls entrance windows roofs neutral','#B8BAB5')]
np.savez_compressed(R/'color-mesh.npz',vertices=m.vertices,faces=m.faces,materials=a);(R/'palette.json').write_text(json.dumps(pal,indent=2)+'\n');q={'palette':[{'id':i,'name':name,'hex':col,'faces':int((a==i).sum())}for i,(name,col)in enumerate(pal)],'domain_face_indices':D,'coplanar_components':len(cs),'partial_color_incomplete':True,'fully_colored_exterior':False,'geometry_policy':'2860 original triangles unchanged','limits':['Roof upper surfaces are truncated proxies, not verified full main roof slopes. Do not color upper or rear planes.', 'Lower long canopy extends beyond image edges; pillars are obscured by flower arrangements/ribbons and people, so no full-column gray replication.', 'Balcony pale masonry infill and gray surrounds differ; coarse original shallow recess is not automatic evidence of precise material correspondence.', 'Glass backings contain frames, interiors and reflections, not single dark glass finish.', 'Small central tile canopy mixes pale weights and dark tiles; no whole gray/black plate.', 'Side/back artificial cuts, low parapets/ground/steps and all unlisted surfaces remain unknown neutral.', 'Original2860faces and immutable OBJ retained without geometry change. New optional partial color variant uses only4evidenced faces, other surfaces unknown neutral.', 'Original scene/preview/model/OBJ files not overwritten; countdelta0.', 'Only24mm nominal entrance facade depth; flat rear is an artificial section boundary, not surveyed rear elevation. Not entire international residence.', 'Exactly2 original official photographs downloaded once successfully and viewed. Rawphotos/retrieval records remain private for authorized backup.']};(R/'appearance-materials.json').write_text(json.dumps(q,indent=2)+'\n');(R/'COLOR-ASSIGNMENT-QA.json').write_text(json.dumps({'status':'PASS','original_STL_sha256':expected,'triangles':2860,'color_mesh_sha256':H(R/'color-mesh.npz')},indent=2));print(q['palette'],'components',len(cs))
